async function sendZeptoMail(params) {
  const zeptoMailUrl = process.env.ZEPTOMAIL_URL || defaultZeptoMailUrl;
  const zeptoMailToken = process.env.ZEPTOMAIL_TOKEN;
  const fromEmail = process.env.ZEPTOMAIL_FROM_EMAIL;
  if (!zeptoMailToken || !fromEmail) {
    throw new Error("Faltan variables ZEPTOMAIL_TOKEN o ZEPTOMAIL_FROM_EMAIL");
  }
  const response = await fetch(zeptoMailUrl, {
    method: "POST",
    signal: AbortSignal.timeout(6e4),
    headers: {
      "Content-Type": "application/json",
      Authorization: zeptoMailToken
    },
    body: JSON.stringify({
      from: {
        address: fromEmail
      },
      to: [
        {
          email_address: {
            address: params.toEmail,
            name: params.toName
          }
        }
      ],
      bcc: params.bccEmails && params.bccEmails.length > 0 ? params.bccEmails.map((email) => ({
        email_address: {
          address: email
        }
      })) : void 0,
      subject: params.subject,
      htmlbody: params.htmlbody,
      attachments: params.attachments && params.attachments.length > 0 ? params.attachments.map((attachment) => ({
        name: attachment.name,
        mime_type: attachment.mimeType,
        content: attachment.content
      })) : void 0
    })
  });
  if (response.ok) return;
  const responseText = await response.text();
  throw new Error(
    `Error enviando correo de confirmaci\xF3n (${response.status}): ${responseText}`
  );
}

