// lib/posthog/server.ts
import { randomUUID } from "crypto";
import { PostHog } from "posthog-node@5.28.9";
function getPostHogConfig() {
  const apiKey = process.env.POSTHOG_PROJECT_TOKEN ?? process.env.NEXT_PUBLIC_POSTHOG_TOKEN ?? process.env.NEXT_PUBLIC_POSTHOG_PROJECT_TOKEN;
  const host = process.env.POSTHOG_HOST ?? process.env.NEXT_PUBLIC_POSTHOG_HOST ?? "https://us.i.posthog.com";
  if (!apiKey || !host) {
    return null;
  }
  return {
    apiKey,
    host: host.replace(/\/$/, "")
  };
}
async function captureServerEvent(params) {
  const config = getPostHogConfig();
  if (!config) return;
  const distinctId = params.distinctId ?? `server:${randomUUID()}`;
  const client = new PostHog(config.apiKey, {
    host: config.host,
    flushAt: 1,
    flushInterval: 0
  });
  try {
    client.capture({
      distinctId,
      event: params.event,
      properties: {
        ...params.properties,
        $process_person_profile: false
      }
    });
  } catch (error) {
    console.error("Error enviando evento a PostHog:", error);
  } finally {
    await client.shutdown();
  }
}

// lib/posthog/emailDelivery.ts
async function captureEmailDelivery(params) {
  try {
    await captureServerEvent({
      event: POSTHOG_EVENTS.emailSendResult,
      distinctId: `submission:${params.collection}:${params.submissionId}`,
      properties: {
        submission_id: params.submissionId,
        collection: params.collection,
        form_name: params.collection === "contactos" ? "contact" : "risk_calculator",
        email_type: params.emailType,
        email_status: params.status,
        email_attempt: params.attempt,
        email_provider: "zeptomail",
        provider_status: params.providerStatus,
        error_code: params.errorCode
      }
    });
  } catch {
    console.error("No se pudo registrar email_send_result en PostHog");
  }
}

// lib/riskCalculatorBookingToken.ts
import { createHash, randomBytes } from "node:crypto";
import { z } from "zod@4.3.6";
var RISK_BOOKING_TOKENS_COLLECTION = "risk_booking_tokens";
var DEFAULT_TOKEN_TTL_DAYS = 14;
var ttlDaysSchema = z.coerce.number().int().min(1).max(30);
function hashRiskBookingToken(rawToken) {
  return createHash("sha256").update(rawToken).digest("hex");
}
function generateRiskBookingToken() {
  return randomBytes(32).toString("base64url");
}
function resolveRiskBookingTokenTtlDays() {
  return ttlDaysSchema.parse(
    process.env.RISK_CALCULATOR_BOOKING_TOKEN_TTL_DAYS ?? DEFAULT_TOKEN_TTL_DAYS
  );
}
function buildRiskBookingTokenExpiryDate(ttlDays) {
  return new Date(Date.now() + ttlDays * 24 * 60 * 60 * 1e3);
}
async function createRiskBookingTokenRecord(params) {
  const rawToken = generateRiskBookingToken();
  const tokenHash = hashRiskBookingToken(rawToken);
  const ttlDays = params.ttlDays ?? resolveRiskBookingTokenTtlDays();
  const expiresAt = buildRiskBookingTokenExpiryDate(ttlDays).toISOString();
  await params.pb.collection(RISK_BOOKING_TOKENS_COLLECTION).create({
    token_hash: tokenHash,
    submission_id: params.submissionId,
    email: params.email.trim().toLowerCase(),
    expires_at: expiresAt,
    used_at: null
  });
  return { rawToken, tokenHash, expiresAt };
}

// lib/riskCalculatorEmail.ts
var RISK_CALCULATOR_ORIGIN_LEGACY = "web_risk_calculator";
var RISK_CALCULATOR_ORIGIN_PENDING = "web_risk_calculator_email_pending";
var RISK_CALCULATOR_ORIGIN_SENT_BOOKING = "web_risk_calculator_email_sent_booking";
var RISK_CALCULATOR_ORIGIN_SENT_DELAYED = "web_risk_calculator_email_sent_delayed";
var riskCalculatorPendingOrigins = [
  RISK_CALCULATOR_ORIGIN_LEGACY,
  RISK_CALCULATOR_ORIGIN_PENDING
];
function isRiskCalculatorPendingOrigin(origin) {
  if (!origin) return false;
  return riskCalculatorPendingOrigins.includes(
    origin
  );
}

// lib/email/sendRiskDiagnosticEmail.ts
function canSendRiskDiagnosticEmail(record) {
  return isRiskCalculatorPendingOrigin(record.origen) && ["", "pending", "failed"].includes(record.email_estado ?? "");
}
async function sendRiskDiagnosticEmail(pb, record, variant, appBaseUrl) {
  if (!canSendRiskDiagnosticEmail(record)) return "skipped";
  await pb.collection("diagnosticos_riesgo").update(record.id, {
    email_estado: "sending",
    "email_intentos+": 1,
    email_ultimo_intento: (/* @__PURE__ */ new Date()).toISOString(),
    email_ultimo_error: ""
  });
  const deliveryEvent = {
    collection: "diagnosticos_riesgo",
    submissionId: record.id,
    emailType: variant === "form_copy" ? "risk_form_copy" : "risk_followup",
    attempt: Number(record.email_intentos || 0) + 1
  };
  let deliveryStarted = false;
  try {
    const params = buildRiskCalculatorEmailParamsFromRecord(record);
    if (!params.toEmail) throw new Error("Diagn\xF3stico sin correo corporativo");
    let agendaLink;
    if (variant === "followup_no_booking") {
      if (!appBaseUrl) throw new Error("Falta URL de agendamiento");
      const { rawToken } = await createRiskBookingTokenRecord({
        pb,
        submissionId: record.id,
        email: params.toEmail
      });
      agendaLink = `${appBaseUrl}/agendar-sesion?token=${encodeURIComponent(rawToken)}`;
    }
    deliveryStarted = true;
    await sendRiskCalculatorResultsEmail({
      ...params,
      emailVariant: variant,
      agendaLink
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : "";
    const status = message.match(/\((\d{3})\)/)?.[1];
    const uncertain = deliveryStarted && !status;
    const summary = status ? `ZeptoMail HTTP ${status}${message.includes("Credit exhausted") ? ": cr\xE9ditos agotados" : ""}` : uncertain ? "Env\xEDo incierto: revisar ZeptoMail antes de reintentar" : "No se pudo preparar el correo del diagn\xF3stico";
    await captureEmailDelivery({
      ...deliveryEvent,
      status: uncertain ? "uncertain" : "failed",
      providerStatus: status ? Number(status) : void 0,
      errorCode: message.includes("Credit exhausted") ? "credit_exhausted" : uncertain ? "delivery_uncertain" : status ? "provider_rejected" : "preparation_failed"
    });
    await pb.collection("diagnosticos_riesgo").update(record.id, {
      email_estado: uncertain ? "sending" : "failed",
      email_ultimo_error: summary
    });
    throw new Error(summary);
  }
  await captureEmailDelivery({ ...deliveryEvent, status: "accepted" });
  await pb.collection("diagnosticos_riesgo").update(record.id, {
    origen: variant === "form_copy" ? RISK_CALCULATOR_ORIGIN_SENT_BOOKING : RISK_CALCULATOR_ORIGIN_SENT_DELAYED,
    email_estado: "sent",
    email_enviado_en: (/* @__PURE__ */ new Date()).toISOString(),
    email_ultimo_error: ""
  });
  return "sent";
}

// lib/email/dispatchPendingRiskEmails.ts
async function dispatchPendingRiskEmails(pb, appBaseUrl) {
  const now = /* @__PURE__ */ new Date();
  const pendingRecords = await pb.collection("diagnosticos_riesgo").getFullList({
    filter: `(origen = "${RISK_CALCULATOR_ORIGIN_PENDING}" || origen = "${RISK_CALCULATOR_ORIGIN_LEGACY}") && created <= "${now.toISOString()}"`
  });
  let evaluated = 0;
  let sent = 0;
  let skipped = 0;
  let failed = 0;
  for (const record of pendingRecords) {
    evaluated += 1;
    if (!canSendRiskDiagnosticEmail(record)) {
      skipped += 1;
      continue;
    }
    const bookingExists = await pb.collection("reservas_reuniones").getList(1, 1, {
      filter: `submission_id = "${record.id}" && estado = "confirmada"`
    });
    if (bookingExists.totalItems > 0 && record.email_estado !== "failed") {
      skipped += 1;
      continue;
    }
    try {
      await sendRiskDiagnosticEmail(
        pb,
        record,
        bookingExists.totalItems > 0 ? "form_copy" : "followup_no_booking",
        appBaseUrl
      );
      sent += 1;
    } catch (error) {
      failed += 1;
      console.error(
        `Error enviando correo diferido para diagn\xF3stico ${record.id}:`,
        error
      );
    }
  }
  return { evaluated, sent, skipped, failed };
}

// .railway/src/risk-calculator-cron.ts
function required(name) {
  const value = process.env[name];
  if (!value) throw new Error(`Missing variable: ${name}`);
  return value;
}
try {
  const pb = new PocketBase(required("POCKET_BASE_URL"));
  pb.beforeSend = (url, options) => ({
    url,
    options: { ...options, signal: AbortSignal.timeout(6e4) }
  });
  await pb.collection("_superusers").authWithPassword(
    required("POCKET_BASE_ADMIN_EMAIL"),
    required("POCKET_BASE_ADMIN_PASSWORD")
  );
  required("ZEPTOMAIL_TOKEN");
  required("ZEPTOMAIL_FROM_EMAIL");
  const appUrl = new URL(required("APP_URL"));
  if (appUrl.protocol !== "https:") throw new Error("APP_URL must use HTTPS");
  const stats = await dispatchPendingRiskEmails(pb, appUrl.origin);
  console.log(JSON.stringify({ success: stats.failed === 0, stats }));
  if (stats.failed > 0) process.exitCode = 1;
} catch (error) {
  console.error(
    JSON.stringify({
      success: false,
      error: error instanceof Error ? error.name : "UnknownError"
    })
  );
  process.exitCode = 1;
}
